import React from 'react';

export default function SectionHeading({ eyebrow, heading, align = 'left' }) {
  return (
    <div className={align === 'center' ? 'text-center' : 'text-left'}>
      <p className="font-mono text-sm text-indigo-500 dark:text-indigo-400 mb-2">{eyebrow}</p>
      <h2 className="font-display text-3xl sm:text-4xl font-semibold tracking-tight text-zinc-900 dark:text-zinc-50">
        {heading}
      </h2>
    </div>
  );
}
